public class LeaderboardTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.util.List<int[]> rows(int[][] data) {
        java.util.List<int[]> list = new java.util.ArrayList<>();
        for (int[] row : data) {
            list.add(row);
        }
        return list;
    }

    static String ids(java.util.List<int[]> scores) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < scores.size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(scores.get(i)[0]);
        }
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        java.util.List<int[]> a = rows(new int[][]{{1, 50}, {2, 80}, {3, 50}});
        Leaderboard.rank(a);
        check("basic ranking", "[2, 1, 3]", ids(a));

        java.util.List<int[]> b = rows(new int[][]{{5, 10}, {2, 10}, {9, 10}});
        Leaderboard.rank(b);
        check("all tied -> id ascending", "[2, 5, 9]", ids(b));

        java.util.List<int[]> c = rows(new int[][]{{1, 5}, {2, 15}, {3, 25}});
        Leaderboard.rank(c);
        check("ascending input gets reversed", "[3, 2, 1]", ids(c));

        java.util.List<int[]> d = rows(new int[][]{{1, -5}, {2, 0}, {3, -5}});
        Leaderboard.rank(d);
        check("negative scores", "[2, 1, 3]", ids(d));

        java.util.List<int[]> e = rows(new int[][]{{4, 90}, {7, 20}});
        Leaderboard.rank(e);
        check("already ranked stays put", "[4, 7]", ids(e));

        java.util.List<int[]> f = rows(new int[][]{{8, 1}});
        Leaderboard.rank(f);
        check("single row", "[8]", ids(f));

        java.util.List<int[]> g = rows(new int[][]{});
        Leaderboard.rank(g);
        check("empty list", "[]", ids(g));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

