public class Leaderboard {

    public static void rank(java.util.List<int[]> scores) {
        java.util.Comparator<int[]> byScoreDesc =
                java.util.Comparator.comparingInt((int[] row) -> row[1]).reversed();
        scores.sort(byScoreDesc.thenComparingInt(row -> row[0]));
    }
}
